import csv
import io
import re


def parse_csv(raw_csv: str):
    records = list(csv.reader(io.StringIO(raw_csv, newline="")))
    if not records:
        return {"columns": [], "rows": []}

    def nonempty(row):
        return sum(bool(value.strip()) for value in row)

    first = next((i for i, row in enumerate(records) if nonempty(row)), None)
    if first is None:
        return {"columns": [], "rows": []}

    if max((nonempty(row) for row in records[first:]), default=0) > 1:
        header_index = next(
            (i for i in range(first, len(records)) if nonempty(records[i]) >= 2),
            first,
        )
    else:
        header_index = first

    header = records[header_index][:]
    data_start = header_index + 1

    if data_start < len(records):
        second = records[data_start]
        filled = [i for i, value in enumerate(second) if value.strip()]
        width = max(len(header), len(second))
        top = header + [""] * (width - len(header))
        bottom = second + [""] * (width - len(second))

        looks_like_subheader = (
            len(filled) >= 2
            and filled[0] > 0
            and any(not top[i].strip() for i in filled)
            and any(top[i].strip() for i in filled)
            and all(
                not re.search(r"\d|[£$€]", bottom[i])
                for i in filled
            )
        )

        if looks_like_subheader:
            merged = []
            parent = ""
            for upper, lower in zip(top, bottom):
                upper = upper.strip()
                lower = lower.strip()
                if upper:
                    parent = upper
                if lower:
                    if parent and lower.casefold() != parent.casefold():
                        merged.append(parent + " - " + lower)
                    else:
                        merged.append(lower)
                else:
                    merged.append(upper)
            header = merged
            data_start += 1

    data = records[data_start:]
    width = max([len(header)] + [len(row) for row in data])
    header += [""] * (width - len(header))

    columns = []
    used = set()
    for index, name in enumerate(header):
        base = name.strip() or "column_" + str(index + 1)
        candidate = base
        suffix = 2
        while candidate in used:
            candidate = base + "_" + str(suffix)
            suffix += 1
        used.add(candidate)
        columns.append(candidate)

    rows = [row + [""] * (width - len(row)) for row in data]
    return {"columns": columns, "rows": rows}
